class P(property): pass
class A:
 @P
 def x(self): return 7
a=A()
print(a.x,type(A.x) is P,A.x.fget(a),A.x.__name__,A.x.__get__(None,A) is A.x)

class P(property):
 def __get__(self,obj,owner=None): print("get"); return 9
class A: x=P(lambda self:7)
a=A()
print(a.x,property.__get__(A.__dict__["x"],a,A))

class P(property):
 def __set_name__(self,owner,name):
  print("name",name)
  property.__set_name__(self,owner,name)
class A: x=P(lambda self:7)
print(A.x.__name__)

class P(property):
 def __init__(self,f): print(self.fget is None)
p=P(lambda self:7)
print(p.fget is None)

class W(staticmethod):
 def __init__(self,f): print(hasattr(self,"__func__"))
w=W(lambda x:x)
print(w.__func__ is None)

class W(classmethod):
 def __init__(self,f): print(hasattr(self,"__func__"))
w=W(lambda x:x)
print(w.__func__ is None)

class S(staticmethod): pass
class A:
 @S
 def f(x): return x+1
print(A.f(7),A().f(9),A.__dict__["f"](11))

class C(classmethod): pass
class A:
 @C
 def f(cls): return cls
class B(A): pass
print(A.f() is A,A().f() is A,B.f() is B,type(A.f).__name__)

class S(staticmethod):
 def __get__(self,obj,owner=None): print("get"); return lambda x:x+2
class A: f=S(lambda x:x)
print(A.f(7))

class S(super):
 def __init__(self,*args): print("init",len(args)); super.__init__(self,*args)
class A:
 def f(self): return 7
class B(A): pass
B.link=S(B)
b=B()
s=b.link
print(type(s) is S,s.f(),B.link.__self__ is None)

class S(super):
 def __init__(self): print(self.__thisclass__ is None,self.__self__ is None,self.__self_class__ is None)
s=S()

class S(super):
 def __getattribute__(self,name):
  print(name)
  return object.__getattribute__(self,name)
class A:
 def f(self): return 7
class B(A): pass
print(S(B,B()).f())

import helper
Module=type(helper)
class M(Module):
 def __getattribute__(self,name):
  if name=="special": return 7
  return object.__getattribute__(self,name)
m=M("named")
m.__getattr__=lambda name:9
print(m.special,m.missing,m.__name__)

import helper
Module=type(helper)
class M(Module): __slots__=("__weakref__",)

class P(property): pass
class G:
 def __getattribute__(self,name):
  if name=="__doc__": print(p.fget is self); return "document"
  return object.__getattribute__(self,name)
 def __call__(self,obj): return 7
p=property.__new__(P)
g=G()
property.__init__(p,g)
print(p.__doc__)

class P(property): pass
class G:
 def __getattribute__(self,name):
  if name=="__doc__": raise ValueError("failed")
  return object.__getattribute__(self,name)
p=property.__new__(P)
g=G()
try: property.__init__(p,g)
except ValueError: print(p.fget is g)
